from solution import multiply
import pytest
from hypothesis import given
import hypothesis.strategies as st


def _expected(a, b):
    # Obviously-correct reference: unit digit is last digit of absolute value.
    return abs(a) % 10 * (abs(b) % 10)


# --- Explicit examples from the spec docstring ---

def test_example_148_412_returns_16():
    assert multiply(148, 412) == 16

def test_example_19_28_returns_72():
    assert multiply(19, 28) == 72

def test_example_2020_1851_returns_0():
    assert multiply(2020, 1851) == 0

def test_example_14_neg15_returns_20():
    assert multiply(14, -15) == 20


# --- Negative numbers: unit digit ignores sign ---

def test_negative_unit_digit_19_28():
    # unit digits 9 and 8 -> 72; naive Python a % 10 gives 1 for -19
    assert multiply(-19, 28) == 72

def test_negative_unit_digit_neg14_neg15():
    # unit digits 4 and 5 -> 20
    assert multiply(-14, -15) == 20

def test_negative_single_digits():
    assert multiply(-9, -8) == 72
    assert multiply(-9, 8) == 72
    assert multiply(9, -8) == 72

def test_negative_ending_1_to_9():
    # every negative -11..-19 must behave like positive 11..19
    assert multiply(-11, 2) == 2
    assert multiply(-12, 3) == 6
    assert multiply(-13, 3) == 9
    assert multiply(-16, 7) == 42
    assert multiply(-17, -18) == 56


# --- Properties derived from spec ---

@given(
    a=st.integers(min_value=-10000, max_value=10000),
    b=st.integers(min_value=-10000, max_value=10000),
)
def test_property_matches_abs_reference_model(a, b):
    assert multiply(a, b) == _expected(a, b)

@given(
    a=st.integers(min_value=-10000, max_value=10000),
    b=st.integers(min_value=-10000, max_value=10000),
)
def test_property_sign_invariance(a, b):
    # unit digits do not depend on sign (spec example uses -15 as 5)
    assert multiply(a, b) == multiply(abs(a), abs(b))
    assert multiply(a, b) == multiply(-abs(a), abs(b))
    assert multiply(a, b) == multiply(abs(a), -abs(b))
    assert multiply(a, b) == multiply(-abs(a), -abs(b))

@given(
    a=st.integers(min_value=-10000, max_value=10000),
    b=st.integers(min_value=-10000, max_value=10000),
)
def test_property_commutativity(a, b):
    assert multiply(a, b) == multiply(b, a)

@given(
    a=st.integers(min_value=-10000, max_value=10000),
    b=st.integers(min_value=-10000, max_value=10000),
    k=st.integers(min_value=-100, max_value=100),
    m=st.integers(min_value=-100, max_value=100),
)
def test_property_only_last_digit_matters(a, b, k, m):
    # adding multiples of 10 does not change unit digits
    assert multiply(a + 10 * k, b + 10 * m) == multiply(a, b)

@given(
    a=st.integers(min_value=0, max_value=9),
    b=st.integers(min_value=0, max_value=9),
)
def test_property_single_digit_is_plain_product(a, b):
    assert multiply(a, b) == a * b

@given(
    a=st.integers(min_value=-10000, max_value=10000),
    b=st.integers(min_value=-10000, max_value=10000),
)
def test_property_range_zero_to_81(a, b):
    r = multiply(a, b)
    assert isinstance(r, int)
    assert 0 <= r <= 81

@given(a=st.integers(min_value=-10000, max_value=10000))
def test_property_trailing_zero_gives_zero(a):
    # any number ending in 0 has unit digit 0
    assert multiply(a, 0) == 0
    assert multiply(a, 10) == 0
    assert multiply(a, -10) == 0
    assert multiply(a, 2020) == 0
    assert multiply(0, a) == 0
